Algorithm Guess
  Define secret As Integer;
  Read secret;
  Define low As Integer <- 1;
  Define high As Integer <- 100;
  Define middle As Integer;
  Define attempts As Integer <- 0;
  Repeat
    middle <- (low + high) Div 2;
    attempts <- attempts + 1;
    If middle < secret Then
      low <- middle + 1;
    Else
      If middle > secret Then
        high <- middle - 1;
      EndIf
    EndIf
  Until middle = secret
  Write "Attempts: ", attempts;
EndAlgorithm

Algorithm SortedSearch
  Dimension v[15] As Integer;
  For i <- 0 To 14 Do
    v[i] <- i * 3 + 2;
  EndFor
  Define searched As Integer;
  Read searched;
  Define low As Integer <- 0;
  Define high As Integer <- 14;
  Define position As Integer <- -1;
  Define steps As Integer <- 0;
  While low <= high And position = -1 Do
    Define middle As Integer <- (low + high) Div 2;
    steps <- steps + 1;
    If v[middle] = searched Then
      position <- middle;
    Else
      If v[middle] < searched Then
        low <- middle + 1;
      Else
        high <- middle - 1;
      EndIf
    EndIf
  EndWhile
  Write "Position: ", position, " in ", steps, " steps";
EndAlgorithm

Algorithm Selection
  Dimension v[5] As Integer;
  For i <- 0 To 4 Do
    Read v[i];
  EndFor
  For i <- 0 To 3 Do
    Define smallest As Integer <- i;
    For j <- i + 1 To 4 Do
      If v[j] < v[smallest] Then
        smallest <- j;
      EndIf
    EndFor
    Define saved As Integer <- v[i];
    v[i] <- v[smallest];
    v[smallest] <- saved;
  EndFor
  For Each n In v Do
    Write n;
  EndFor
EndAlgorithm

Algorithm FastPrime
  Define n As Integer;
  Read n;
  Define isPrime As Boolean <- n >= 2;
  Define divisions As Integer <- 0;
  Define d As Integer <- 2;
  While d * d <= n And isPrime Do
    divisions <- divisions + 1;
    If n Mod d = 0 Then
      isPrime <- False;
    EndIf
    d <- d + 1;
  EndWhile
  Write isPrime, " with ", divisions, " divisions";
EndAlgorithm
